const { createCanvas, loadImage } = require('@napi-rs/canvas');

exports.handler = async (event, context) => {
    try {
            const query = event.queryStringParameters || {};
                    const username = query.username || 'CR██████';
                            const tag = query.tag || '@ye9dev';
                                    const serverName = query.server || 'HORIZON KINGDOM';
                                            const level = query.level || '1';
                                                    const rep = query.rep || '+0';
                                                            const shinza = query.shinza || '0';
                                                                    const rank = query.rank || '1';
                                                                            const xp = parseInt(query.xp || '5', 10);
                                                                                    const maxXP = parseInt(query.maxXP || '100', 10);
                                                                                            const messages = query.messages || '1';
                                                                                                    const voice = query.voice || '0 min';
                                                                                                            const avatarUrl = query.avatar || 'https://cdn.discordapp.com/embed/avatars/0.png';

                                                                                                                    const canvas = createCanvas(934, 282);
                                                                                                                            const ctx = canvas.getContext('2d');

                                                                                                                                    // خلفية البطاقة الداكنة
                                                                                                                                            ctx.fillStyle = '#131315';
                                                                                                                                                    ctx.fillRect(0, 0, canvas.width, canvas.height);

                                                                                                                                                            // صورة الأفاتار الدائرية مع إطار
                                                                                                                                                                    try {
                                                                                                                                                                                const avatar = await loadImage(avatarUrl);
                                                                                                                                                                                            ctx.save();
                                                                                                                                                                                                        ctx.beginPath();
                                                                                                                                                                                                                    ctx.arc(110, 141, 65, 0, Math.PI * 2, true);
                                                                                                                                                                                                                                ctx.closePath();
                                                                                                                                                                                                                                            ctx.clip();
                                                                                                                                                                                                                                                        ctx.drawImage(avatar, 45, 76, 130, 130);
                                                                                                                                                                                                                                                                    ctx.restore();

                                                                                                                                                                                                                                                                                ctx.strokeStyle = '#2f3136';
                                                                                                                                                                                                                                                                                            ctx.lineWidth = 4;
                                                                                                                                                                                                                                                                                                        ctx.beginPath();
                                                                                                                                                                                                                                                                                                                    ctx.arc(110, 141, 65, 0, Math.PI * 2, true);
                                                                                                                                                                                                                                                                                                                                ctx.stroke();
                                                                                                                                                                                                                                                                                                                                        } catch (e) {
                                                                                                                                                                                                                                                                                                                                                    // تخطي في حال فشل تحميل الأفاتار
                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                    // عنوان السيرفر في الأعلى
                                                                                                                                                                                                                                                                                                                                                                            ctx.fillStyle = '#ffffff';
                                                                                                                                                                                                                                                                                                                                                                                    ctx.font = 'bold 13px sans-serif';
                                                                                                                                                                                                                                                                                                                                                                                            ctx.textAlign = 'center';
                                                                                                                                                                                                                                                                                                                                                                                                    ctx.fillText(serverName.toUpperCase(), 550, 35);

                                                                                                                                                                                                                                                                                                                                                                                                            ctx.fillStyle = '#72767d';
                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.font = '9px sans-serif';
                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.fillText('YOUR KINGDOM, YOUR RULES', 550, 50);

                                                                                                                                                                                                                                                                                                                                                                                                                                    // اسم المستخدم والـ Tag
                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.textAlign = 'left';
                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.fillStyle = '#ffffff';
                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.font = 'bold 26px sans-serif';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.fillText(username, 210, 85);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.fillStyle = '#72767d';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.font = '14px sans-serif';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.fillText(tag, 210, 110);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // الإحصائيات الجانبية على اليسار (LVL, REP, SHINZA, RANK)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.textAlign = 'center';

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // LVL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.fillStyle = '#72767d';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.font = '10px sans-serif';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.fillText('LVL', 65, 235);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.fillStyle = '#ffffff';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.font = 'bold 18px sans-serif';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.fillText(level, 65, 258);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // REP
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.fillStyle = '#72767d';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.font = '10px sans-serif';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.fillText('REP', 115, 235);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.fillStyle = '#ffffff';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.font = 'bold 18px sans-serif';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.fillText(rep, 115, 258);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // SHINZA
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.fillStyle = '#72767d';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.font = '10px sans-serif';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.fillText('SHINZA', 175, 235);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.fillStyle = '#ffffff';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.font = 'bold 18px sans-serif';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.fillText(shinza, 175, 258);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // RANK
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.fillStyle = '#72767d';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.font = '10px sans-serif';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.textAlign = 'left';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.fillText('RANK', 235, 235);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.fillStyle = '#ffffff';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.font = 'bold 18px sans-serif';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.fillText(`#${rank}`, 235, 258);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // قسم تقدم الخبرة (XP PROGRESS)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.fillStyle = '#ffffff';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.font = 'bold 12px sans-serif';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.fillText('XP PROGRESS', 210, 150);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // شريط الخبرة (Background)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.fillStyle = '#2f3136';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.beginPath();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (typeof ctx.roundRect === 'function') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ctx.roundRect(210, 162, 520, 16, 8);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.rect(210, 162, 520, 16);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.fill();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // شريط التقدم الفعلي (Fill)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const progressWidth = Math.min(Math.max((xp / maxXP) * 520, 16), 520);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.fillStyle = '#ffffff';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.beginPath();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (typeof ctx.roundRect === 'function') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ctx.roundRect(210, 162, progressWidth, 16, 8);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.rect(210, 162, progressWidth, 16);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.fill();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // قيم الـ XP بجانب الشريط
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.fillStyle = '#b9bbbe';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.font = '11px sans-serif';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.textAlign = 'right';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.fillText(`${xp} / ${maxXP} XP`, 730, 150);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // المعلومات السفلية (TOTAL XP, Messages, Voice)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.textAlign = 'left';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.font = '12px sans-serif';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.fillStyle = '#b9bbbe';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.fillText(`TOTAL XP: ${xp}`, 330, 258);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ctx.fillText(`Messages: ${messages}`, 470, 258);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ctx.fillText(`Voice: ${voice}`, 610, 258);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const buffer = canvas.toBuffer('image/png');

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        statusCode: 200,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    headers: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'Content-Type': 'image/png',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            body: buffer.toString('base64'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        isBase64Encoded: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        statusCode: 500,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    body: JSON.stringify({ error: error.message }),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                